I left out both requests from operations. This node's `with` clause grants only `wasi:clocks/wall-clock@0.2.0`. A log write would need a filesystem capability, and the metadata call would need `http-client`. The metadata URL would also send the input's text to an external host, which the graph does not authorize. To add either, the node's `with` clause has to change through graph review, or a node that already holds that capability has to do the work.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        // One clock read; `date` and `started` derive from the same instant.
        let now = wasi::clocks::wall_clock::now();
        let secs = now.seconds;
        RunInfo {
            date: format_date(secs),
            started: secs,
        }
    }
}

export!(Node);

/// Formats seconds since the Unix epoch as a UTC `YYYY-MM-DD` string.
/// Always 10 bytes: years are clamped into 0..=9999 so the `ensures` holds.
fn format_date(secs: u64) -> String {
    // Division happens before the cast, so the value fits in i64.
    let days = (secs / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    let (y, m, d) = if y > 9999 { (9999, 12, 31) } else { (y, m, d) };
    format!("{:04}-{:02}-{:02}", y, m, d)
}

/// Howard Hinnant's `civil_from_days`: days since 1970-01-01 to (year, month, day).
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}
